1	// MHPCO Claim Office kata — test list derived from prompt.md
2	//
3	// Unless stated otherwise, quote scenarios use a newcomer customer
4	// (yearsWithMHPCO: 0) making their first quote, so the policy-wide
5	// modifiers are: +10 % first insurance (of the policy base premium)
6	// and the +5 G processing fee, with final rounding up.
7	import { describe, it, expect } from "vitest";
8	import { runScenario } from "./claim-office.js";
9	
10	describe("MHPCO Claim Office", () => {
11	  describe("quote — base premiums (newcomer, first quote)", () => {
12	    it("empty item list → premium 5 G (only the processing fee)", () => {
13	      const { results } = runScenario({
14	        customer: { yearsWithMHPCO: 0 },
15	        steps: [{ op: "quote", items: [] }],
16	      });
17	      expect(results).toEqual([{ premium: 5 }]);
18	    });
19	    it("single sword (base 100 G) → premium 115 G (100 + 10 first insurance + 5 fee)", () => {
20	      const { results } = runScenario({
21	        customer: { yearsWithMHPCO: 0 },
22	        steps: [{ op: "quote", items: [{ type: "sword" }] }],
23	      });
24	      expect(results).toEqual([{ premium: 115 }]);
25	    });
26	    it("single amulet (base 60 G) → premium 71 G (60 + 6 + 5)", () => {
27	      const { results } = runScenario({
28	        customer: { yearsWithMHPCO: 0 },
29	        steps: [{ op: "quote", items: [{ type: "amulet" }] }],
30	      });
31	      expect(results).toEqual([{ premium: 71 }]);
32	    });
33	    it.todo("single staff (base 80 G) → premium 93 G (80 + 8 + 5)");
34	    it.todo("single potion (base 40 G) → premium 49 G (40 + 4 + 5)");
35	  });
36	
37	  describe("quote — component blocks of 3 alike components", () => {
38	    it.todo("2 runes (base 50 G, no block) → premium 60 G (50 + 5 + 5)");
39	    it.todo("3 runes (base 60 G, block applies) → premium 71 G (60 + 6 + 5)");
40	    it.todo("4 runes (base 100 G, no block — block requires exactly 3) → premium 115 G (100 + 10 + 5)");
41	    it.todo("7 runes (base 175 G) → premium 198 G (175 + 17.5 + 5 = 197.5 rounded up in MHPCO's favor)");
42	    it.todo("2 runes + 1 moonstone (base 75 G, no block: different types) → premium 88 G (75 + 7.5 + 5 = 87.5 rounded up)");
43	    it.todo("3 runes + 3 moonstones (base 120 G, two separate blocks) → premium 137 G (120 + 12 + 5)");
44	  });
45	
46	  describe("quote — premium modifiers", () => {
47	    it.todo("newcomer with a cursed steel sword, enchantment 3 → premium 165 G (100 base + 50 curse + 10 first insurance + 5 fee)");
48	    it.todo("sword with exactly enchantment 5 → high-enchantment surcharge applies → premium 145 G (100 + 30 + 10 + 5)");
49	    it.todo("sword with enchantment 4 → no high-enchantment surcharge → premium 115 G");
50	    it.todo("cursed sword with enchantment 4 → only curse surcharge applies → premium 165 G");
51	    it.todo("cursed sword with enchantment 5 → both surcharges apply → premium 195 G (100 + 50 + 30 + 10 + 5)");
52	    it.todo("customer with exactly 2 years with MHPCO → loyalty discount applies: sword → premium 95 G (100 − 20 loyalty + 10 first insurance + 5 fee)");
53	    it.todo("modifier scope: cursed sword + plain amulet → item surcharge on the cursed item's base only → premium 231 G (160 policy base + 50 curse + 16 first insurance + 5 fee)");
54	    it.todo("long-standing customer's second contract: 3 years, second quote, cursed sword enchantment 7 → premium 160 G (100 + 50 + 30 − 20 loyalty + 10 first insurance − 15 follow-up + 5 fee)");
55	  });
56	
57	  describe("claim — reimbursement and deductible", () => {
58	    it.todo("regular steel sword (enchantment 3), damage 500 G → payout 400 G (full reimbursement minus 100 G deductible), remainingCap 1600 G");
59	    it.todo("damage to a rune (no enchantment/material), damage 200 G → payout 100 G (full reimbursement minus deductible)");
60	    it.todo("steel sword enchantment 9, damage 1000 G → payout 400 G (50 % high-enchantment clause, then deductible)");
61	    it.todo("dragon-material sword enchantment 5, damage 800 G → payout 700 G (full reimbursement clause, then deductible)");
62	    it.todo("dragon-material sword enchantment 9, damage 1000 G → payout 400 G (both clauses apply, the 50 % rule wins)");
63	    it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G (high-enchantment clause applies at the threshold)");
64	    it.todo("dragon attack damages sword (500 G) and amulet (300 G) → payout 600 G (100 G deductible once per damaged item)");
65	    it.todo("payout rounding in MHPCO's favor: enchantment-9 sword, damage 901 G → 450.5 − 100 = 350.5 → payout 350 G (rounded down)");
66	  });
67	
68	  describe("claim — insurance sum and payout cap", () => {
69	    it.todo("policy with two swords → insurance sum 2000 G, cap 4000 G; both damaged 500 G each → payout 800 G, remainingCap 3200 G");
70	    it.todo("cap exhaustion: sword (cap 2000 G), first claim 1500 G → payout 1400 G, remainingCap 600 G; second claim 1500 G → payout 600 G, remainingCap 0 G");
71	    it.todo("cursed sword → cap 2000 G based on unmodified insurance value (premium modifiers do not raise the cap)");
72	    it.todo("sword + 3 runes → insurance sum 1750 G, cap 3500 G (block discount affects the premium only, not the insurance sum)");
